mapping.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
const root='/home/apnex/taceng/agp';
const packet=path.join(root,'docs/reviews/direct-peer-send-assurance');
const read=p=>fs.readFileSync(path.join(packet,p),'utf8');
const sha=data=>crypto.createHash('sha256').update(data).digest('hex');
const mapping=read('direct-peer-acceptance-mapping.md');
const manifest=JSON.parse(read('direct-peer-input-manifest.json'));
const key=JSON.parse(read('direct-peer-answer-key.json'));
const questions=JSON.parse(read('direct-peer-questions.json'));
const families=['family-1','family-2','family-3'];
const cells=Object.values(manifest.arms).flatMap(arm=>families.map(f=>[arm.label,f]));
const outcomes=cells.flatMap(([arm,f])=>questions.questions.map(q=>[arm,f,q.id]));
const slots=outcomes.flatMap(([arm,f,q])=>families.filter(j=>j!==f).map(j=>[arm,f,q,j]));
assert.equal(cells.length,6); assert.equal(outcomes.length,72); assert.equal(slots.length,144);
assert.equal(new Set(slots.map(s=>JSON.stringify(s))).size,144);
assert.ok(slots.every(s=>s[1]!==s[3]));
const tableRows=[...mapping.matchAll(/^\| (Q\d{2}) \| (\d+) \| (\d+) \| (\d+) \|$/gm)].map(m=>[m[1],...m.slice(2).map(Number)]);
assert.deepEqual(tableRows,key.entries.map(q=>[q.id,q.required.length,q.wrong.length,q.judgeGuidance?.length??0]));
assert.equal(key.entries.reduce((n,q)=>n+q.required.length,0),53);
assert.equal(key.entries.reduce((n,q)=>n+q.wrong.length,0),35);
assert.equal(key.entries.reduce((n,q)=>n+(q.judgeGuidance?.length??0),0),7);
assert.equal(Object.keys(key.scoring).length,3); assert.equal(key.rules.length,7);
assert.deepEqual(key.entries.map(q=>q.id),questions.questions.map(q=>q.id));
assert.deepEqual(key.entries.filter(q=>q.role==='control').map(q=>q.id),manifest.coverage.controls);
const projections=key.entries.map(entry=>({id:entry.id,question:questions.questions.find(q=>q.id===entry.id).prompt,required:entry.required,wrong:entry.wrong,judgeGuidance:entry.judgeGuidance??[]}));
for(const p of projections) assert.deepEqual(Object.keys(p),['id','question','required','wrong','judgeGuidance']);
const payloadBytes=Object.fromEntries(Object.entries(manifest.arms).map(([role,arm])=>{
 const total=Buffer.byteLength(read(arm.path))+Buffer.byteLength(read('direct-peer-reader-instructions.md'))+Buffer.byteLength(read('direct-peer-questions.json'));
 assert.ok(total<=manifest.limits.readerPayloadBytes);
 return [role,total];
}));
assert.deepEqual(payloadBytes,{baseline:35902,candidate:52784});
assert.equal(manifest.limits.readerPayloadBytes,65536); assert.equal(manifest.limits.responseBytes,24576);
const links=[...mapping.matchAll(/\]\(([^)\s]+)\)/g)].map(([,target])=>({target,resolved:path.resolve(packet,target.split('#')[0])}));
for(const link of links) if(!link.resolved.endsWith('/direct-peer-acceptance-mapping-checks.json')) assert.ok(fs.existsSync(link.resolved),link.target);
assert.ok(!/[^\x00-\x7f]/u.test(mapping));
assert.ok(!/[ \t]+$/m.test(mapping));
const instructions=read('direct-peer-reader-instructions.md');
const operations=execFileSync('git',['show','d17feb9ea7cec067176804e7e3c25f92281e6d04:docs/OPERATIONS.md'],{cwd:'/home/apnex/taceng/context-lab',encoding:'utf8'});
assert.ok(instructions.includes('using its identifier as a heading'));
assert.ok(!instructions.includes('###'));
assert.ok(operations.includes('### <answerHeading>'));
// Arithmetic illustrations only: this is not a public-record reader or execution scorer.
const vectors=()=>Object.fromEntries(questions.questions.map(q=>[q.id,[2,2,2]]));
const calculate=(baseline,candidate)=>{
 const sum=v=>v.reduce((a,b)=>a+b,0);
 const floor=Object.values(candidate).every(v=>v.filter(s=>s===2).length>=2&&!v.includes(0));
 const controls=manifest.coverage.controls.every(q=>sum(candidate[q])>=sum(baseline[q]));
 const strict=questions.questions.some(({id})=>sum(candidate[id])>sum(baseline[id]));
 return {floor,controls,strict,numericConditions:floor&&controls&&strict};
};
const cases=[];
function example(name,modify,expected) {
 const baseline=vectors(); const candidate=vectors();
 modify(baseline,candidate);
 const result=calculate(baseline,candidate);
 assert.equal(result.numericConditions,expected,name);
 cases.push({name,...result});
}
example('all ties',()=>{},false);
example('strict Q09 improvement',b=>{b.Q09=[2,2,1];},true);
example('control regression despite another gain',(b,c)=>{b.Q09=[2,2,1];c.Q01=[2,2,1];},false);
example('candidate zero despite two top scores',(b,c)=>{c.Q01=[2,2,0];},false);
example('candidate floor despite mean improvement',(b,c)=>{b.Q01=[0,0,0];c.Q01=[2,1,1];},false);
example('integration regression allowed with floor and another gain',(b,c)=>{c.Q09=[2,2,1];b.Q12=[2,2,1];},true);
const quoteCaps=[{votes:[2,2],cap:1,result:1},{votes:[0,2],cap:1,result:0},{votes:[2,2],cap:2,result:2}];
for(const t of quoteCaps) assert.equal(Math.min(...t.votes,t.cap),t.result);
console.log(JSON.stringify({
 artifact:{path:path.join(packet,'direct-peer-acceptance-mapping.md'),sha256:sha(mapping),bytes:Buffer.byteLength(mapping)},
 enumeratedPopulation:{cells:cells.length,questionOutcomes:outcomes.length,expectedVoteSlots:slots.length,unique:true,sameFamilySlots:0},
 keyInventoryMatchesDocument:true,
 sourceProjection:{kind:'allowlisted source inventory only; no actual judge prompt rendered',commonSha256:sha(JSON.stringify({scoring:key.scoring,rules:key.rules})),questions:projections.map(p=>({id:p.id,sha256:sha(JSON.stringify(p))}))},
 payloadBytes,
 existingLocalLinksChecked:links.filter(l=>!l.resolved.endsWith('/direct-peer-acceptance-mapping-checks.json')).length,
 pendingReceiptLink:'direct-peer-acceptance-mapping-checks.json',
 headingContractDifferenceConfirmed:true,
 arithmeticExamples:cases,
 quoteCapExamples:quoteCaps,
 scope:'Offline source, arithmetic and document checks only; no runtime binding or independent assurance result.'
},null,2));
NODE

